using System.Globalization;
using MessagePack;

namespace Receipts.GeneratedTests;

public class DecimalFormatterPrecisionReceiptTests
{
    [Theory]
    [InlineData("1.2345")]
    [InlineData("0.001")]
    [InlineData("-123.456789")]
    public void DecimalRoundTripsWithoutLosingDigits(string text)
    {
        decimal value = decimal.Parse(text, NumberStyles.Number, CultureInfo.InvariantCulture);
        byte[] bytes = MessagePackSerializer.Serialize(value);
        decimal result = MessagePackSerializer.Deserialize<decimal>(bytes);
        Assert.Equal(value, result);
    }
}

